using HRIS.Api.Common; using HRIS.Api.DTOs.ServiceAward; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class ServiceAwardService:IServiceAwardService { private readonly IServiceAwardRepository _repo; private readonly IEmployeeRepository _employees; private readonly IAuditLogService _audit; private readonly IReferenceRepository _refs; public ServiceAwardService(IServiceAwardRepository repo,IEmployeeRepository employees,IAuditLogService audit,IReferenceRepository refs){_repo=repo;_employees=employees;_audit=audit;_refs=refs;} public async Task<List<ServiceAwardResponseDto>> GetAsync(UserContext actor){if(actor.EmployeeId is null && !actor.IsHrOrSupport) throw new ForbiddenException("Akun ini tidak terhubung ke Employee."); var employees=await _employees.GetAllAsync(); if(!actor.IsHrOrSupport){var own=employees.FirstOrDefault(x=>x.Id==actor.EmployeeId);var ownEmployment=own?.Employments.FirstOrDefault(x=>x.EndDate==null);if(ownEmployment is not null&&!await _refs.IsModuleAllowedAsync(ownEmployment.EmploymentTypeId,"5")) return new List<ServiceAwardResponseDto>();} var today=DateOnly.FromDateTime(DateTime.UtcNow);foreach(var e in employees.Where(x=>x.IsActive)){var years=today.Year-e.JoinDate.Year;if(today < e.JoinDate.AddYears(years))years--;var max=years>=5?years:4;for(var n=5;n<=max;n+=5){if(!await _repo.ExistsAsync(e.Id,n))await _repo.AddAsync(new ServiceAward{EmployeeId=e.Id,ServiceYears=n,DueDate=e.JoinDate.AddYears(n),Status="Pending"});}var next=Math.Max(5,((Math.Max(years,0)/5)+1)*5);if(next<=years+5&&!await _repo.ExistsAsync(e.Id,next))await _repo.AddAsync(new ServiceAward{EmployeeId=e.Id,ServiceYears=next,DueDate=e.JoinDate.AddYears(next),Status="Pending"});}var allAwards=await _repo.GetAllAsync(); if(!actor.IsHrOrSupport) allAwards=allAwards.Where(x=>x.EmployeeId==actor.EmployeeId).ToList(); return allAwards.Select(x=>new ServiceAwardResponseDto{Id=x.Id,EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",ServiceYears=x.ServiceYears,DueDate=x.DueDate,Status=x.Status,GivenAt=x.GivenAt}).ToList();} public async Task MarkStatusAsync(int id,string status,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh mengubah service award.");var x=await _repo.GetByIdAsync(id)??throw new NotFoundException("Service award tidak ditemukan.");if(status=="Reminded"){if(x.Status!="Pending")throw new BadRequestException("Award ini bukan Pending.");x.Status="Reminded";}else if(status=="Given"){if(x.Status!="Pending"&&x.Status!="Reminded")throw new BadRequestException("Award belum siap ditandai diberikan.");x.Status="Given";x.GivenAt=DateTime.UtcNow;}else throw new BadRequestException("Status hanya Reminded atau Given.");await _repo.UpdateAsync(x);if(actor.IsSupport)await _audit.LogAsync(actor.UserId,"ServiceAward.Status",nameof(ServiceAward),id,$"Status menjadi {status}");} }
